def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    danger_bids = []
    affordable_pressures = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    danger_bids.append(bid)
                if bid <= budget * 1.2:
                    affordable_pressures.append(bid)

    if not alive_opps:
        return float(min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    base = 20.0 + 18.0 * scarcity

    if hp >= 8 and no_water_days == 0:
        base -= 4.0
    if hp <= 5:
        base += 18.0
    if hp <= 3:
        base += 28.0
    if no_water_days >= 1:
        base += 16.0
    if no_water_days >= 2:
        base += 28.0

    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        practical = max(40.0, avg_prev)
        if danger_bids:
            practical = max(practical, max(danger_bids) + 2.0)
        elif affordable_pressures:
            practical = max(practical, max(affordable_pressures) + 1.5)
        else:
            practical = max(practical, min(max_prev * 0.72, budget * 0.55))

        if max_prev >= 150 and hp >= 7 and no_water_days == 0 and supply >= 20:
            base = min(base, 24.0)
        else:
            base = max(base, practical * (0.72 + 0.18 * scarcity))

    reserve_days = max(0, 10 - day)
    soft_cap = budget / max(1, reserve_days)
    if hp >= 7 and no_water_days == 0:
        cap = max(22.0, soft_cap * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        cap = max(40.0, soft_cap * 2.2)
    else:
        cap = max(30.0, soft_cap * 1.45)

    if hp <= 2 or no_water_days >= 2:
        cap = max(cap, budget)
        base = max(base, 0.82 * budget)

    bid = min(base, cap, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    alive = []
    for agent_id, st in opponents_status.items():
        if st.get('alive', False):
            alive.append((agent_id, st))

    if not alive:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer opponent aggressiveness
    yesterday_bids = []
    for _, st in alive:
        prev = st.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # If someone was extremely aggressive yesterday, increase our bid to avoid being outbid.
    extreme = highest_prev_bid >= (DAILY_SALARY * 6.0)  # e.g., Cindy's 915

    # Supply pressure: higher supply usually reduces competition; lower supply increases it.
    # Map supply in [15,25] -> competition factor in [1.0,0.6]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, t))
    comp_factor = 1.0 - 0.4 * t  # 1.0 at 15, 0.6 at 25

    # Base bid target: aim around 0.55-0.75 salary depending on hp.
    if my_hp <= 2:
        base = DAILY_SALARY * 0.9
    elif my_hp <= 5:
        base = DAILY_SALARY * 0.7
    else:
        base = DAILY_SALARY * 0.6

    # Adjust for extreme opponent behavior
    if extreme:
        base *= 1.25

    # Final target scales with competition
    target = base * comp_factor

    # Additional small bump if we are low on budget relative to target
    if my_budget < target:
        target = my_budget

    # Never bid more than we can afford
    bid = min(my_budget, target)

    # If budget is very low, still try to secure water proportionally
    if my_budget <= DAILY_SALARY * 0.2:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    # Ensure non-negative bid
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents) + 1

    if num_alive <= 1:
        return 1.0

    avg_supply_per_player = supply / num_alive

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if avg_supply_per_player >= WATER_REQ:
        base_bid = DAILY_SALARY * 0.3
    else:
        base_bid = DAILY_SALARY * 0.7

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        bid = max(base_bid, highest_prev * 0.5)
    else:
        bid = base_bid

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], bid * 1.5)

    return min(my_status['budget'], float(bid))
